      "revealjs",
      join("pandoc", "title-fancy/title-slide.scss"),
    );
    return sassLayer(titleBlockScss);
  }
}

function isLegacyTitleStyle(format: Format) {
  return format.metadata["title-slide-style"] === kStylePandoc;
}

